@section('content')
<section class="portal-card"><span class="demo-badge">TEST MODE · SAMPLE DATA ONLY</span><h1 style="margin-top:16px">Your Service Book / ඔබගේ සේවා පොත</h1><p class="portal-muted">Find your service details with a part serial number. No username or password.<br>කොටසේ serial number එක ඇතුළත් කර සේවා විස්තර බලන්න.</p><p class="portal-muted">This demonstration does not send WhatsApp messages. Demo codes appear on this screen.</p>
<form id="lookupForm"><label for="lookupSerial">Serial number / අනුක්‍රමික අංකය</label><input id="lookupSerial" maxlength="100" autocomplete="off" required placeholder="Try DEMO-001"><button type="submit" style="margin-top:14px">Continue / ඉදිරියට →</button></form>
<p><button type="button" class="sample" data-serial="DEMO-001">Try DEMO-001</button> <button type="button" class="sample" data-serial="DEMO-002">Try DEMO-002</button></p>
<div id="lookupStatus" role="status" aria-live="polite"></div></section>
<section id="verifyCard" class="portal-card" hidden><h2>Verify your number / දුරකථන අංකය තහවුරු කරන්න</h2><p id="maskedPhone"></p><p class="portal-muted">In the connected system, a code or secure link will be sent to the number registered with this service record.</p><div class="demo-code" id="demoCode"></div><form id="verifyForm"><label for="verifyCode">Verification code / තහවුරු කිරීමේ කේතය</label><input id="verifyCode" inputmode="numeric" autocomplete="one-time-code" maxlength="6" pattern="[0-9]{6}" required><button type="submit" style="margin-top:14px">View Service Details / විස්තර බලන්න</button></form><p><button type="button" id="resendCode">New demo code</button></p><div id="verifyStatus" role="status" aria-live="polite"></div></section>
<section id="serviceCard" class="portal-card" hidden><span class="demo-badge">DEMONSTRATION RECORD</span><h2 style="margin-top:16px" id="vehicleName"></h2><div id="vehiclePlate" class="vehicle-summary"></div><div class="portal-grid"><div><small>Part / කොටස</small><p id="partName"></p></div><div><small>Serial number</small><p id="partSerial"></p></div></div><h2>Service History / සේවා ඉතිහාසය</h2><div id="demoServices"></div><h2 style="margin-top:22px">Warranty / වගකීම</h2><p id="demoWarranty"></p><p class="portal-muted">Sample dates and terms for layout testing only. These are not CCS warranty promises.</p><button type="button" id="startAgain">Search another serial / නැවත සොයන්න</button></section>
<style>.demo-badge{display:inline-block;padding:6px 10px;background:#ffcc00;color:#21310c;font-size:11px;font-weight:800;border-radius:20px}.demo-code{border:1px dashed #75bd9f;padding:14px;margin:16px 0;color:#ffdf61;border-radius:8px}.sample{background:#244a45;color:#d9f6e8;margin:4px 0;font-size:12px}#lookupStatus,#verifyStatus{margin-top:12px}.demo-service{padding:14px 0;border-bottom:1px solid #315451}#partSerial{overflow-wrap:anywhere}</style>
<script>
(()=>{
 const $=id=>document.getElementById(id);
 // Deliberately isolated fixtures: no database, customer API, credentials or real phone numbers.
 const samples={
 'DEMO-001':{vehicle:'Toyota Aqua · Sample Vehicle',plate:'DEMO CAR 01',phone:'07• ••• ••01',part:'Hybrid battery module',services:[['12 Oct 2026','Module replacement and battery check','82,000 km'],['20 Oct 2026','Follow-up inspection','82,600 km']],warranty:'Sample approved warranty · 12 Oct 2026 – 12 Apr 2027'},
 'DEMO-002':{vehicle:'Toyota Prius · Sample Vehicle',plate:'DEMO CAR 02',phone:'07• ••• ••02',part:'ABS unit',services:[['15 Oct 2026','ABS unit installation and inspection','95,000 km']],warranty:'No approved warranty information in this sample.'}
 };
 let active=null,code='',expires=0,attempts=0;
 function clear(){active=null;code='';expires=0;attempts=0;$('verifyCard').hidden=true;$('serviceCard').hidden=true;$('verifyCode').value='';$('lookupStatus').textContent='';$('verifyStatus').textContent='';}
 function issue(){const values=new Uint32Array(1);crypto.getRandomValues(values);code=String(100000+values[0]%900000);expires=Date.now()+120000;attempts=0;$('verifyCode').value='';$('verifyStatus').textContent='';$('demoCode').textContent='DEMO CODE: '+code+' · expires in 2 minutes · not sent to WhatsApp';}
 $('lookupSerial').addEventListener('input',clear);
 $('lookupForm').addEventListener('submit',event=>{event.preventDefault();clear();const serial=$('lookupSerial').value.trim().toUpperCase();if(!samples[serial]){$('lookupStatus').textContent='Demo record not found. Use DEMO-001 or DEMO-002.';return;}active=serial;issue();$('maskedPhone').textContent='Registered number: '+samples[serial].phone;$('verifyCard').hidden=false;$('verifyCard').scrollIntoView({behavior:'smooth',block:'start'});$('verifyCode').focus();});
 document.querySelectorAll('[data-serial]').forEach(button=>button.addEventListener('click',()=>{$('lookupSerial').value=button.dataset.serial;$('lookupForm').requestSubmit();}));
 $('resendCode').addEventListener('click',()=>{if(active)issue();});
 $('verifyForm').addEventListener('submit',event=>{event.preventDefault();if(!active)return;if(Date.now()>expires){$('verifyStatus').textContent='Code expired. Request a new demo code.';return;}if(attempts>=5){$('verifyStatus').textContent='Too many attempts. Request a new demo code.';return;}attempts++;if($('verifyCode').value.trim()!==code){$('verifyStatus').textContent='Incorrect code. Please try again.';return;}const data=samples[active];$('vehicleName').textContent=data.vehicle;$('vehiclePlate').textContent=data.plate;$('partName').textContent=data.part;$('partSerial').textContent=active;$('demoWarranty').textContent=data.warranty;const area=$('demoServices');area.replaceChildren();for(const service of data.services){const row=document.createElement('div');row.className='demo-service';const title=document.createElement('strong');title.textContent=service[0];const info=document.createElement('p');info.textContent=service[1]+' · '+service[2];row.append(title,info);area.append(row);}code='';expires=0;$('verifyCard').hidden=true;$('serviceCard').hidden=false;$('serviceCard').scrollIntoView({behavior:'smooth',block:'start'});});
 $('startAgain').addEventListener('click',()=>{clear();$('lookupSerial').value='';$('lookupSerial').focus();});
 const serial=new URLSearchParams(location.search).get('serial');if(serial){$('lookupSerial').value=serial.slice(0,100);$('lookupForm').requestSubmit();}
})();
</script>
@endsection
